input.new_string:
if p1 < 0 or p2 < 0:
    raise ValueError("points cannot be negative")

# Check if game is over and validate the score is reachable
if max(p1, p2) >= 4 and abs(p1 - p2) >= 2:
    winner_points = max(p1, p2)
    loser_points = min(p1, p2)
    # If loser has <= 2 points, winner must have exactly 4 (game ends at 4-0, 4-1, 4-2)
    # If loser has >= 3 points (deuce occurred), winner must have exactly loser + 2
    if loser_points <= 2:
        if winner_points != 4:
            raise ValueError("game would have ended earlier")
    else:
        if winner_points != loser_points + 2:
            raise ValueError("game would have ended earlier")
    return "Game Player 1" if p1 > p2 else "Game Player 2"

# Deuce/Advantage situations
if p1 >= 3 and p2 >= 3:
    if p1 == p2:
        return "Deuce"
    # In long deuce (both >= 5), advantage naming is swapped
    if p1 >= 5 and p2 >= 5:
        return "Advantage Player 1" if p1 < p2 else "Advantage Player 2"
    return "Advantage Player 1" if p1 > p2 else "Advantage Player 2"

# Normal scores: use "-All" for equal scores
if p1 == p2:
    return f"{CALLS[p1]}-All"
return f"{CALLS[p1]}-{CALLS[p2]}"
